export function canonicalJson(root) {
  const out = [];
  const pending = [root]; // values still to write, and literal text wrapped as { text }
  const literal = (text) => ({ text });
  while (pending.length > 0) {
    const item = pending.pop();
    if (item !== null && typeof item === 'object' && Object.hasOwn(item, 'text') && item instanceof Literal) {
      out.push(item.text);
    } else if (Array.isArray(item)) {
      const parts = [new Literal('[')];
      item.forEach((element, i) => parts.push(...(i > 0 ? [new Literal(','), element] : [element])));
      parts.push(new Literal(']'));
      for (let i = parts.length - 1; i >= 0; i -= 1) pending.push(parts[i]);
    } else if (item !== null && typeof item === 'object') {
      const parts = [new Literal('{')];
      Object.keys(item).sort().forEach((key, i) => {
        parts.push(new Literal(`${i > 0 ? ',' : ''}${JSON.stringify(key)}:`), item[key]);
      });
      parts.push(new Literal('}'));
      for (let i = parts.length - 1; i >= 0; i -= 1) pending.push(parts[i]);
    } else {
      out.push(JSON.stringify(item));
    }
  }
